select id, recipient_id, actor_id, type, target_type, target_id, params, create_time
from notification
where recipient_id = #{recipientId}
  and type in

    #{type}

  and (#{lastCreatedAt} is null
        or create_time < #{lastCreatedAt}
        or (create_time = #{lastCreatedAt} and id < #{lastId}))
order by create_time desc, id desc
limit #{size}

SELECT COUNT(*)
FROM notification n
LEFT JOIN notification_read_state r
    ON r.recipient_id = n.recipient_id AND r.notification_group = #{notificationGroup}
WHERE n.recipient_id = #{recipientId}
    AND n.type IN

    #{type}

    AND n.id > COALESCE(r.last_read_id, 0)
